corrected_code:
const express = require('express');
const diagnostics_channel = require('diagnostics_channel');

const app = express();

const queryChannel = diagnostics_channel.channel('db:query');
const queryExecutionLog = new Map();

queryChannel.subscribe((message) => {
  queryExecutionLog.set(message.queryExecutionId, {
    sql: message.sql,
    parameters: message.parameters,
    durationMs: message.duration,
    tenantId: message.tenantId
  });
});

app.get('/api/diagnostics/queries/:queryExecutionId', (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const entry = queryExecutionLog.get(req.params.queryExecutionId);
  if (!entry) {
    return res.status(404).json({ error: 'Execution record expired or not found' });
  }

  // Strictly enforce tenant boundary and mask parameters to prevent PII leakage
  if (entry.tenantId !== req.user.tenantId) {
    return res.status(403).json({ error: 'Access denied: cannot inspect cross-tenant query diagnostics' });
  }

  res.json({
    queryExecutionId: req.params.queryExecutionId,
    sql: entry.sql,
    durationMs: entry.durationMs,
    parametersMasked: '[REDACTED_PII]'
  });
});

app.listen(5005);
